export const accountHome=user=>user?.role==='admin'?'/admin':user?.role==='supplier'?'/supplier':'/account';
async function api(path,body,method){const response=await fetch(path,{method:method||(body===undefined?'GET':'POST'),cache:'no-store',headers:{'Content-Type':'application/json'},...(body!==undefined&&body!==null?{body:JSON.stringify(body)}:{})});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.message||'Не удалось сохранить данные. Проверьте соединение и повторите.');return data;}
export const commerceRequest=(action,body)=>api('/api/commerce'+(action?'/'+action:''),action?body||{}:undefined);
export const invitationRequest=(action,body,method)=>api('/api/invitations'+(action?'/'+action:''),body,method);
export function rememberInvitation(){const token=location.hash.match(/^#\/invite\/([a-f0-9]{64})$/)?.[1];if(token)sessionStorage.setItem('vera-invitation',token);}
export const invitationToken=()=>sessionStorage.getItem('vera-invitation')||'';
export const clearInvitation=()=>sessionStorage.removeItem('vera-invitation');
export function invitationView(user,esc){return `<section class="auth-page wrap"><div class="auth-card"><p class="eyebrow">VERA PRIVÉ · СОТРУДНИЧЕСТВО</p><h1>Ваш кабинет поставщика</h1><p class="small muted">Войдите с той почтой, на которую пришло приглашение. После принятия вам будут доступны ваши товары, продажи и выплаты.</p>${user?`<p>Вы вошли как ${esc(user.email)}.</p>${user.emailVerified?'<button class="btn wide" data-action="accept-invite">Принять приглашение</button>':'<button class="btn wide" data-action="verify-invite">Подтвердить почту кодом</button>'}`:'<a class="btn wide" href="#/auth/login">Войти</a><div class="auth-links"><a href="#/auth/register">Создать аккаунт</a></div>'}</div></section>`;}
